def norm(S):
    mr=min(r for r,c in S); mc=min(c for r,c in S)
    return frozenset((r-mr,c-mc) for r,c in S)
def orientations(S):
    nrm=norm(S)
    # transformations on bbox width/height via coordinate formulas in unbounded plane
    out=[]
    for k in range(4):
        pts=set(S)
        for _ in range(k): pts={(c,-r) for r,c in pts}
        for flip in [False,True]:
            y=pts if not flip else {(r,-c) for r,c in pts}
            out.append(norm(y))
    return set(out)

def shape_key(S):
    return min(tuple(sorted(x)) for x in orientations(S))
