def comps(points,diag=True):
    pts=set(points); out=[]
    while pts:
        s={pts.pop()}; q=list(s)
        while q:
            r,c=q.pop()
            for dr in [-1,0,1]:
              for dc in [-1,0,1]:
                if dr==dc==0 or (not diag and abs(dr)+abs(dc)!=1):continue
                p=(r+dr,c+dc)
                if p in pts:pts.remove(p);s.add(p);q.append(p)
        out.append(s)
    return sorted(out,key=lambda s:(min(r for r,c in s),min(c for r,c in s)))
